import{_ as l,a0 as p,w as s,s as u,I as i,a1 as r,A as o,x as t,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"Manjaro 18.1（KDE）安裝圖解 | LCTT x X-CMD","titleTemplate":false,"description":"Manjaro 18.1（KDE）安裝圖解 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Manjaro 18.1（KDE）安裝圖解 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Manjaro 18.1（KDE）安裝圖解 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190923 Installation Guide of Manjaro 18.1 (KDE Edition) with Screenshots","title":"Manjaro 18.1（KDE）安裝圖解","tag":"201910","desc":""},"relativePath":"201910/20190923 Installation Guide of Manjaro 18.1 (KDE Edition) with Screenshots.md","filePath":"[post].md"}'),d={name:"201910/20190923 Installation Guide of Manjaro 18.1 (KDE Edition) with Screenshots.md"};function h(m,a,w,j,c,b){const n=p("Link");return s(),u("div",null,[i("p",null,[r(n,{href:"collector:",title:"lujun9972"},{default:o(()=>[...a[0]||(a[0]=[t("#",-1)])]),_:1}),a[5]||(a[5]=t(": subject: (Installation Guide of Manjaro 18.1 (KDE Edition) with Screenshots) ",-1)),r(n,{href:"collector:",title:"lujun9972"},{default:o(()=>[...a[1]||(a[1]=[t("#",-1)])]),_:1}),a[6]||(a[6]=t(": via: (",-1)),r(n,{href:"https://www.linuxtechi.com/install-manjaro-18-1-kde-edition-screenshots/"},{default:o(()=>[...a[2]||(a[2]=[t("https://www.linuxtechi.com/install-manjaro-18-1-kde-edition-screenshots/",-1)])]),_:1}),a[7]||(a[7]=t(") ",-1)),r(n,{href:"collector:",title:"lujun9972"},{default:o(()=>[...a[3]||(a[3]=[t("#",-1)])]),_:1}),a[8]||(a[8]=t(": author: (Pradeep Kumar ",-1)),r(n,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:o(()=>[...a[4]||(a[4]=[t("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),a[9]||(a[9]=t(")",-1))]),a[28]||(a[28]=e('<h1 id="manjaro-18-1-kde-安裝圖解" tabindex="-1">Manjaro 18.1（KDE）安裝圖解 <a class="header-anchor" href="#manjaro-18-1-kde-安裝圖解" aria-label="Permalink to “Manjaro 18.1（KDE）安裝圖解”">​</a></h1><p>在 Manjaro 18.0（Illyria）發佈一年之際，該團隊發佈了他們的下一個重要版本，即 Manjaro 18.1，代號為 “Juhraya”。該團隊還發布了一份官方聲明，稱 Juhraya 包含了許多改進和錯誤修復。</p><h3 id="manjaro-18-1-中的新功能" tabindex="-1">Manjaro 18.1 中的新功能 <a class="header-anchor" href="#manjaro-18-1-中的新功能" aria-label="Permalink to “Manjaro 18.1 中的新功能”">​</a></h3><p>以下列出了 Manjaro 18.1 中的一些新功能和增強功能：</p><ul><li>可以在 LibreOffice 或 Free Office 之間選擇</li><li>Xfce 版的新 Matcha 主題</li><li>在 KDE 版本中重新設計了消息傳遞系統</li><li>使用 bhau 工具支持 Snap 和 FlatPak 軟件包</li></ul><h3 id="最小系統需求" tabindex="-1">最小系統需求 <a class="header-anchor" href="#最小系統需求" aria-label="Permalink to “最小系統需求”">​</a></h3><ul><li>1 GB RAM</li><li>1 GHz 處理器</li><li>大約 30 GB 硬盤空間</li><li>互聯網連接</li><li>啓動介質（USB/DVD）</li></ul><h3 id="安裝-manjaro-18-1-kde-版-的分步指南" tabindex="-1">安裝 Manjaro 18.1（KDE 版）的分步指南 <a class="header-anchor" href="#安裝-manjaro-18-1-kde-版-的分步指南" aria-label="Permalink to “安裝 Manjaro 18.1（KDE 版）的分步指南”">​</a></h3><p>要在系統中開始安裝 Manjaro 18.1（KDE 版），請遵循以下步驟：</p><h4 id="步驟-1-下載-manjaro-18-1-iso" tabindex="-1">步驟 1) 下載 Manjaro 18.1 ISO <a class="header-anchor" href="#步驟-1-下載-manjaro-18-1-iso" aria-label="Permalink to “步驟 1) 下載 Manjaro 18.1 ISO”">​</a></h4>',10)),i("p",null,[a[11]||(a[11]=t("在安裝之前，你需要從位於 ",-1)),r(n,{href:"https://manjaro.org/download/official/kde/"},{default:o(()=>[...a[10]||(a[10]=[t("這裏",-1)])]),_:1}),a[12]||(a[12]=t(" 的官方下載頁面下載 Manjaro 18.1 的最新副本。由於我們這裏介紹的是 KDE 版本，因此我們選擇 KDE 版本。但是對於所有桌面環境（包括 Xfce、KDE 和 Gnome 版本），安裝過程都是相同的。",-1))]),a[29]||(a[29]=e('<h4 id="步驟-2-創建-usb-啓動盤" tabindex="-1">步驟 2) 創建 USB 啓動盤 <a class="header-anchor" href="#步驟-2-創建-usb-啓動盤" aria-label="Permalink to “步驟 2) 創建 USB 啓動盤”">​</a></h4><p>從 Manjaro 下載頁面成功下載 ISO 文件後，就可以創建 USB 磁盤了。將下載的 ISO 文件複製到 USB 磁盤中，然後創建可引導磁盤。確保將你的引導設置更改為使用 USB 引導，並重新啓動系統。</p><h4 id="步驟-3-manjaro-live-版安裝環境" tabindex="-1">步驟 3) Manjaro Live 版安裝環境 <a class="header-anchor" href="#步驟-3-manjaro-live-版安裝環境" aria-label="Permalink to “步驟 3) Manjaro Live 版安裝環境”">​</a></h4><p>系統重新啓動時，它將自動檢測到 USB 驅動器，並開始啓動進入 Manjaro Live 版安裝屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Boot-Manjaro-18-1-kde-installation.jpg" alt="Boot-Manjaro-18-1-kde-installation"></p><p>接下來，使用箭頭鍵選擇 “<ruby>啓動：Manjaro x86_64 kde<rt>Boot: Manjaro x86_64 kde</rt></ruby>”，然後按回車鍵以啓動 Manjaro 安裝程序。</p><h4 id="安裝-4-選擇啓動安裝程序" tabindex="-1">安裝 4) 選擇啓動安裝程序 <a class="header-anchor" href="#安裝-4-選擇啓動安裝程序" aria-label="Permalink to “安裝 4) 選擇啓動安裝程序”">​</a></h4><p>接下來，將啓動 Manjaro 安裝程序，如果你已連接到互聯網，Manjaro 將自動檢測你的位置和時區。單擊 “<ruby>啓動安裝程序<rt>Launch Installer</rt></ruby>”，開始在系統中安裝 Manjaro 18.1 KDE 版本。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Choose-Launch-Installaer-Manjaro18-1-kde.jpg" alt="Choose-Launch-Installaer-Manjaro18-1-kde"></p><h4 id="步驟-5-選擇語言" tabindex="-1">步驟 5) 選擇語言 <a class="header-anchor" href="#步驟-5-選擇語言" aria-label="Permalink to “步驟 5) 選擇語言”">​</a></h4><p>接下來，安裝程序將帶你選擇你的首選語言。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Choose-Language-Manjaro18-1-Kde-Installation.jpg" alt="Choose-Language-Manjaro18-1-Kde-Installation"></p><p>選擇你想要的語言，然後單擊“<ruby>下一步<rt>Next</rt></ruby>”。</p><h4 id="步驟-6-選擇時區和區域" tabindex="-1">步驟 6) 選擇時區和區域 <a class="header-anchor" href="#步驟-6-選擇時區和區域" aria-label="Permalink to “步驟 6) 選擇時區和區域”">​</a></h4><p>在下一個屏幕中，選擇所需的時區和區域，然後單擊“<ruby>下一步<rt>Next</rt></ruby>”繼續。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Select-Location-During-Manjaro18-1-KDE-Installation.jpg" alt="Select-Location-During-Manjaro18-1-KDE-Installation"></p><h4 id="步驟-7-選擇鍵盤佈局" tabindex="-1">步驟 7) 選擇鍵盤佈局 <a class="header-anchor" href="#步驟-7-選擇鍵盤佈局" aria-label="Permalink to “步驟 7) 選擇鍵盤佈局”">​</a></h4><p>在下一個屏幕中，選擇你喜歡的鍵盤佈局，然後單擊“<ruby>下一步<rt>Next</rt></ruby>”繼續。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Select-Keyboard-Layout-Manjaro18-1-kde-installation.jpg" alt="Select-Keyboard-Layout-Manjaro18-1-kde-installation"></p><h4 id="步驟-8-選擇分區類型" tabindex="-1">步驟 8) 選擇分區類型 <a class="header-anchor" href="#步驟-8-選擇分區類型" aria-label="Permalink to “步驟 8) 選擇分區類型”">​</a></h4><p>這是安裝過程中非常關鍵的一步。 它將允許你選擇分區方式：</p><ul><li>擦除磁盤</li><li>手動分區</li><li>並存安裝</li><li>替換分區</li></ul><p>如果在 VM（虛擬機）中安裝 Manjaro 18.1，則將看不到最後兩個選項。</p><p>如果你不熟悉 Manjaro Linux，那麼我建議你使用第一個選項（<ruby>擦除磁盤<rt>Erase Disk</rt></ruby>），它將為你自動創建所需的分區。如果要創建自定義分區，則選擇第二個選項“<ruby>手動分區<rt>Manual Partitioning</rt></ruby>”，顧名思義，它將允許我們創建自己的自定義分區。</p><p>在本教程中，我將通過選擇“<ruby>手動分區<rt>Manual Partitioning</rt></ruby>”選項來創建自定義分區：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Manual-Partition-Manjaro18-1-KDE.jpg" alt="Manual-Partition-Manjaro18-1-KDE"></p><p>選擇第二個選項，然後單擊“<ruby>下一步<rt>Next</rt></ruby>”繼續。</p><p>如我們所見，我有 40 GB 硬盤，因此我將在其上創建以下分區，</p><ul><li><code>/boot</code>       –  2GB（ext4）</li><li><code>/</code>           –  10 GB（ext4）</li><li><code>/home</code>      –  22 GB（ext4）</li><li><code>/opt</code>       –  4 GB（ext4）</li><li><ruby>交換分區<rt>Swap</rt></ruby>     –  2 GB</li></ul><p>當我們在上方窗口中單擊“<ruby>下一步<rt>Next</rt></ruby>”時，將顯示以下屏幕，選擇“<ruby>新建分區表<rt>new partition table</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Create-Partition-Table-Manjaro18-1-Installation.jpg" alt="Create-Partition-Table-Manjaro18-1-Installation"></p><p>點擊“<ruby>確定<rt>OK</rt></ruby>”。</p><p>現在選擇可用空間，然後單擊“<ruby>創建<rt>create</rt></ruby>”以將第一個分區設置為大小為 2 GB 的 <code>/boot</code>，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/boot-partition-manjaro-18-1-installation.jpg" alt="boot-partition-manjaro-18-1-installation"></p><p>單擊“<ruby>確定<rt>OK</rt></ruby>”以繼續操作，在下一個窗口中再次選擇可用空間，然後單擊“<ruby>創建<rt>create</rt></ruby>”以將第二個分區設置為 <code>/</code>，大小為 10 GB：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/slash-root-partition-manjaro18-1-installation.jpg" alt="slash-root-partition-manjaro18-1-installation"></p><p>同樣，將下一個分區創建為大小為 22 GB 的 <code>/home</code>：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/home-partition-manjaro18-1-installation.jpg" alt="home-partition-manjaro18-1-installation"></p><p>到目前為止，我們已經創建了三個分區作為主分區，現在創建下一個分區作為擴展分區：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Extended-Partition-Manjaro18-1-installation.jpg" alt="Extended-Partition-Manjaro18-1-installation"></p><p>單擊“<ruby>確定<rt>OK</rt></ruby>”以繼續。</p><p>創建大小分別為 5 GB 和 2 GB 的 <code>/opt</code> 和交換分區作為邏輯分區。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/opt-partition-manjaro-18-1-installation.jpg" alt="opt-partition-manjaro-18-1-installation"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/swap-partition-manjaro18-1-installation.jpg" alt="swap-partition-manjaro18-1-installation"></p><p>完成所有分區的創建後，單擊“<ruby>下一步<rt>Next</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/choose-next-after-partition-creation.jpg" alt="choose-next-after-partition-creation"></p><h4 id="步驟-9-提供用户信息" tabindex="-1">步驟 9) 提供用户信息 <a class="header-anchor" href="#步驟-9-提供用户信息" aria-label="Permalink to “步驟 9) 提供用户信息”">​</a></h4><p>在下一個屏幕中，你需要提供用户信息，包括你的姓名、用户名、密碼、計算機名等：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/User-creation-details-manjaro18-1-installation.jpg" alt="User-creation-details-manjaro18-1-installation"></p><p>提供所有信息後，單擊“<ruby>下一步<rt>Next</rt></ruby>”繼續安裝。</p><p>在下一個屏幕中，系統將提示你選擇辦公套件，因此請做出適合你的選擇：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Office-Suite-Selection-Manjaro18-1.jpg" alt="Office-Suite-Selection-Manjaro18-1"></p><p>單擊“<ruby>下一步<rt>Next</rt></ruby>”以繼續。</p><h4 id="步驟-10-摘要信息" tabindex="-1">步驟 10) 摘要信息 <a class="header-anchor" href="#步驟-10-摘要信息" aria-label="Permalink to “步驟 10) 摘要信息”">​</a></h4><p>在完成實際安裝之前，安裝程序將向你顯示你選擇的所有詳細信息，包括語言、時區、鍵盤佈局和分區信息等。單擊“<ruby>安裝<rt>Install</rt></ruby>”以繼續進行安裝過程。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Summary-manjaro18-1-installation.jpg" alt="Summary-manjaro18-1-installation"></p><h4 id="步驟-11-進行安裝" tabindex="-1">步驟 11) 進行安裝 <a class="header-anchor" href="#步驟-11-進行安裝" aria-label="Permalink to “步驟 11) 進行安裝”">​</a></h4><p>現在，實際的安裝過程開始，一旦完成，請重新啓動系統以登錄到 Manjaro 18.1 KDE 版：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Manjaro18-1-Installation-Progress.jpg" alt="Manjaro18-1-Installation-Progress"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Restart-Manjaro-18-1-after-installation.jpg" alt="Restart-Manjaro-18-1-after-installation"></p><h4 id="步驟-12-安裝成功後登錄" tabindex="-1">步驟 12) 安裝成功後登錄 <a class="header-anchor" href="#步驟-12-安裝成功後登錄" aria-label="Permalink to “步驟 12) 安裝成功後登錄”">​</a></h4><p>重新啓動後，我們將看到以下登錄屏幕，使用我們在安裝過程中創建的用户憑據登錄：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Login-screen-after-manjaro-18-1-installation.jpg" alt="Login-screen-after-manjaro-18-1-installation"></p><p>點擊“<ruby>登錄<rt>Login</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/KDE-Desktop-Screen-Manjaro-18-1.jpg" alt="KDE-Desktop-Screen-Manjaro-18-1"></p><p>就是這樣！你已經在系統中成功安裝了 Manjaro 18.1 KDE 版，並探索了所有令人興奮的功能。請在下面的評論部分中發表你的反饋和建議。</p><hr>',67)),i("p",null,[a[14]||(a[14]=t("via: ",-1)),r(n,{href:"https://www.linuxtechi.com/install-manjaro-18-1-kde-edition-screenshots/"},{default:o(()=>[...a[13]||(a[13]=[t("https://www.linuxtechi.com/install-manjaro-18-1-kde-edition-screenshots/",-1)])]),_:1})]),i("p",null,[a[19]||(a[19]=t("作者：",-1)),r(n,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:o(()=>[...a[15]||(a[15]=[t("Pradeep Kumar",-1)])]),_:1}),a[20]||(a[20]=t(" 選題：",-1)),r(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...a[16]||(a[16]=[t("lujun9972",-1)])]),_:1}),a[21]||(a[21]=t(" 譯者：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...a[17]||(a[17]=[t("wxy",-1)])]),_:1}),a[22]||(a[22]=t(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...a[18]||(a[18]=[t("wxy",-1)])]),_:1})]),i("p",null,[a[25]||(a[25]=t("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[23]||(a[23]=[t("LCTT",-1)])]),_:1}),a[26]||(a[26]=t(" 原創編譯，",-1)),r(n,{href:"https://linux.cn/"},{default:o(()=>[...a[24]||(a[24]=[t("Linux中國",-1)])]),_:1}),a[27]||(a[27]=t(" 榮譽推出",-1))])])}const g=l(d,[["render",h]]);export{M as __pageData,g as default};
